#include <stdlib.h>

#define PAGE_BYTES 4096
#define INTS_PER_PAGE (PAGE_BYTES / (int)sizeof(int))

long solve(const int *data, const int *indices, int n) {
  int pages = (n + INTS_PER_PAGE - 1) / INTS_PER_PAGE;
  int *counts = (int *)calloc((size_t)pages, sizeof(int));
  int *offsets = (int *)calloc((size_t)(pages + 1), sizeof(int));
  int *ordered = (int *)malloc((size_t)n * sizeof(int));
  if (!counts || !offsets || !ordered) {
    free(counts);
    free(offsets);
    free(ordered);
    return 0;
  }

  for (int i = 0; i < n; i++) {
    counts[indices[i] / INTS_PER_PAGE]++;
  }

  for (int p = 0; p < pages; p++) {
    offsets[p + 1] = offsets[p] + counts[p];
  }

  for (int i = 0; i < n; i++) {
    int page = indices[i] / INTS_PER_PAGE;
    ordered[offsets[page]++] = indices[i];
  }

  for (int p = pages; p > 0; p--) {
    offsets[p] = offsets[p - 1];
  }
  offsets[0] = 0;

  long sum = 0;
  for (int i = 0; i < n; i++) {
    sum += data[ordered[i]];
  }

  free(counts);
  free(offsets);
  free(ordered);
  return sum;
}

