#define REPEATS 200

long solve(const unsigned char *scores, int n) {
  long total = 0;
  unsigned char lut[256] = {0};

  for (int s = 0; s <= 100; s++) {
    if (s < 60) lut[s] = 1;
    else if (s < 70) lut[s] = 2;
    else if (s < 80) lut[s] = 4;
    else if (s < 90) lut[s] = 8;
    else lut[s] = 16;
  }

  for (int r = 0; r < REPEATS; r++) {
    for (int i = 0; i < n; i++) {
      total += lut[scores[i]];
    }
  }
  return total;
}
